 *
 * @export
 * @class V3SubgraphProviderWithFallBacks
 */
export class V3SubgraphProviderWithFallBacks extends SubgraphProviderWithFallBacks {
  constructor(fallbacks) {
    super(fallbacks, Protocol.V3);
  }
}
